"""Tests for pangolin_gui/olm_socket.py (generated by Strata, reviewed)."""
from __future__ import annotations

import json
import os
import tempfile
import threading
from http.server import BaseHTTPRequestHandler
from socketserver import ThreadingUnixStreamServer

import pytest

from pangolin_gui.olm_socket import OlmClient, OlmError, parse_status

SAMPLE_STATUS = {
    "connected": True, "registered": True, "terminated": False,
    "version": "1.2.3", "agent": "agent-xyz", "orgId": "org-1", "gatewayActive": True,
    "peers": {
        "1": {"siteId": 1, "name": "relay-peer", "connected": True, "rtt": 5_000_000,
              "lastSeen": "2024-01-01T00:00:00Z", "endpoint": "ep1", "isRelay": True,
              "isLocal": False, "peerAddress": "addr1"},
        "2": {"siteId": 2, "name": "local-peer", "connected": False, "rtt": 12_340_000,
              "lastSeen": "0001-01-01T00:00:00Z", "endpoint": "ep2", "isRelay": False,
              "isLocal": True, "peerAddress": "addr2"},
    },
    "exitNode": {"connected": True, "rtt": 3_000_000, "lastSeen": "2024-06-01T12:00:00Z", "endpoint": "exit-ep"},
    "error": {"code": "ERR01", "message": "something went wrong"},
}


def test_parse_status_full():
    r = parse_status(SAMPLE_STATUS)
    assert (r.connected, r.registered, r.terminated) == (True, True, False)
    assert (r.version, r.agent, r.org_id, r.gateway_active) == ("1.2.3", "agent-xyz", "org-1", True)
    assert (r.error_code, r.error_message) == ("ERR01", "something went wrong")
    assert [p.name for p in r.peers] == ["local-peer", "relay-peer"]
    local, relay = r.peers
    assert (local.site_id, local.connected, local.rtt_ms, local.last_seen) == (2, False, 12.3, None)
    assert (local.is_local, local.is_relay, local.peer_address, local.endpoint) == (True, False, "addr2", "ep2")
    assert (relay.site_id, relay.rtt_ms, relay.last_seen, relay.is_relay) == (1, 5.0, "2024-01-01T00:00:00Z", True)
    assert r.exit_node is not None
    assert (r.exit_node.connected, r.exit_node.rtt_ms, r.exit_node.endpoint) == (True, 3.0, "exit-ep")


def test_parse_status_empty():
    r = parse_status({})
    assert r.connected is False and r.peers == [] and r.exit_node is None
    assert r.error_code == "" and r.org_id == ""


@pytest.fixture
def olm_server(tmp_path):
    base = str(tmp_path)
    if len(base) > 90:  # AF_UNIX path limit
        base = tempfile.mkdtemp(prefix="olm")
    sock_path = os.path.join(base, "olm.sock")
    recorded: list[dict] = []

    class Handler(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"

        def log_message(self, *args):
            pass

        def _send(self, payload, code=200):
            body = json.dumps(payload).encode()
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_GET(self):
            if self.path == "/status":
                self._send(SAMPLE_STATUS)
            else:
                self._send({"error": "not found"}, 404)

        def do_POST(self):
            raw = self.rfile.read(int(self.headers.get("Content-Length", 0)))
            if self.path == "/exit":
                self._send({"status": "ok"})
            elif self.path == "/switch-org":
                recorded.append(json.loads(raw))
                self._send({"status": "ok"})
            else:
                self._send({"error": "not found"}, 404)

    server = ThreadingUnixStreamServer(sock_path, Handler)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    yield sock_path, recorded
    server.shutdown()
    server.server_close()


def test_get_status(olm_server):
    status = OlmClient(olm_server[0]).get_status()
    assert status.connected and len(status.peers) == 2 and status.exit_node is not None


def test_exit(olm_server):
    OlmClient(olm_server[0]).exit()


def test_switch_org(olm_server):
    path, recorded = olm_server
    OlmClient(path).switch_org("org-9")
    assert recorded == [{"org_id": "org-9"}]


def test_is_running(olm_server):
    assert OlmClient(olm_server[0]).is_running() is True


def test_missing_socket(tmp_path):
    client = OlmClient(str(tmp_path / "nope.sock"))
    assert client.is_running() is False
    with pytest.raises(OlmError, match="not running"):
        client.get_status()


def test_unknown_path_raises(olm_server):
    client = OlmClient(olm_server[0])
    with pytest.raises(OlmError, match="HTTP 404"):
        client._request("GET", "/nope")
